mapper.sql:
with detail as ( SELECT SINGLEDEAL.TOTLE_TRADE_ID, SINGLEDEAL.PS, SINGLEDEAL.FINPROD_TYPE2, SINGLEDEAL.trade_date, PADD.portfolio_id, SINGLEDEAL.FINPROD_ID, SINGLEDEAL.TRADE_AMT, SINGLEDEAL.SHARE_AMT FROM TRD_PRODUCT_DEAL SINGLEDEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD PADD ON SINGLEDEAL.TRADE_ID = PADD.TRADE_ID left join FIN_PRODUCT fp on PADD.portfolio_id = fp.FINPROD_MARKET_ID left join FIN_PRODUCT_ADD pa on PA.FINPROD_ID = fp.FINPROD_ID left join sys_user users on users.USER_NAME = pa.prod_manager WHERE SINGLEDEAL.trade_date = to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') and SINGLEDEAL.ps IN ('C1', 'C2', 'C4', 'C5', 'C7', 'C20', 'T01', 'T02', 'T03', 'T04', 'T07', 'T08', 'T09', 'T11', 'T13', 'T23', 'T24', 'T38', 'T39', 'T46', 'T47', 'T48') and fp.P_FINPROD_ID is null and SINGLEDEAL.IS_CANCEL = 'N' and TRADE_STATUS = '01' and TRADE_AMT > 0 and not exists /*只统计外部交易*/ (select 1 from fin_product pro where SINGLEDEAL.counter_id = pro.finprod_market_id)
and users.USER_NAME in
#{item}
union all
SELECT SINGLEDEAL.TOTLE_TRADE_ID, SINGLEDEAL.PS, SINGLEDEAL.FINPROD_TYPE2, SINGLEDEAL.trade_date, PADD.portfolio_id, SINGLEDEAL.FINPROD_ID, SINGLEDEAL.TRADE_AMT, SINGLEDEAL.SHARE_AMT FROM TRD_PRODUCT_DEAL SINGLEDEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD PADD ON SINGLEDEAL.TRADE_ID = PADD.TRADE_ID left join FIN_PRODUCT fp on PADD.portfolio_id = fp.FINPROD_MARKET_ID left join FIN_PRODUCT_ADD pa on PA.FINPROD_ID = fp.FINPROD_ID left join sys_user users on users.USER_NAME = pa.prod_manager WHERE SINGLEDEAL.trade_date = to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') and SINGLEDEAL.ps IN ( 'T22') and fp.P_FINPROD_ID is null and SINGLEDEAL.IS_CANCEL = 'N' and TRADE_STATUS = '01' and SINGLEDEAL.FEE_AMT is null and TRADE_AMT > 0 and not exists /*只统计外部交易*/ (select 1 from fin_product pro where SINGLEDEAL.counter_id = pro.finprod_market_id)
and users.USER_NAME in
#{item}
union all
SELECT SINGLEDEAL.TOTLE_TRADE_ID, SINGLEDEAL.PS, SINGLEDEAL.FINPROD_TYPE2, SINGLEDEAL.trade_date, PADD.portfolio_id, SINGLEDEAL.FINPROD_ID, SINGLEDEAL.TRADE_AMT, SINGLEDEAL.SHARE_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL SINGLEDEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD PADD ON SINGLEDEAL.TOTLE_TRADE_ID = PADD.TRADE_ID left join FIN_PRODUCT fp on PADD.portfolio_id = fp.FINPROD_MARKET_ID left join FIN_PRODUCT_ADD pa on PA.FINPROD_ID = fp.FINPROD_ID left join sys_user users on users.USER_NAME = pa.prod_manager WHERE SINGLEDEAL.trade_date = to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') and SINGLEDEAL.ps IN ( 'T07', 'T08', 'T38') and fp.P_FINPROD_ID is null and SINGLEDEAL.IS_CANCEL = 'N' and TRADE_STATUS = '01' AND SINGLEDEAL.P_TOTLE_TRADE_ID IS not NULL and not exists /*只统计外部交易*/ (select 1 from fin_product pro where SINGLEDEAL.counter_id = pro.finprod_market_id) and SINGLEDEAL.ps in ('T07','T08') and SINGLEDEAL.ps != 'F16'
and users.USER_NAME in
#{item}
)

with DetailFuture as ( select tmp.* from (select distinct '' PS, fcp.PAY_DATE mdate, pp.PORTFOLIO_ID, psp.FINPROD_ID, fp.FINPROD_TYPE2 CASHFLOWTYPE, fcp.CASH_TYPE, case WHEN FP.FINPROD_TYPE2 = 'F01' /*到期还本*100*/ THEN ROUND(psp.AMOUNT * fcp.CASH_AMT, 2) WHEN FP.FINPROD_TYPE2 in ('F16', 'F24') /*产品到期*/ THEN psp.AMOUNT else ROUND(psp.AMOUNT * fcp.CASH_AMT / nvl(fcp.CASH_BASEAMT, 1) / 1, 2) end as CASHFLOW from PTL_SEC_POSITION psp left join PTL_PORTFOLIO pp /*产品组合*/ on psp.PORTFOLIO_ID = pp.PORTFOLIO_ID left join FIN_CASH_PLAN fcp /*资产付息计划*/ on fcp.FINPROD_ID = psp.FINPROD_ID left join FIN_PRODUCT fp /*资产标的*/ on fp.FINPROD_ID = psp.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD /*产品附属表*/ ON (PSP.PORTFOLIO_ID = PRODADD.PORTFOLIO_ID or pp.PARENT_PORTFOLIO_ID = PRODADD.PORTFOLIO_ID) LEFT JOIN FIN_PRODUCT PROD /*产品要素*/ ON PRODADD.FINPROD_ID = PROD.FINPROD_ID where PROD.VDATE <= FCP.MDATE /*过滤掉产品陈立日之前的计划*/ and psp.CDATE = to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') - 1 and FCP.PAY_DATE = to_date(#{searchDateFuture,jdbcType=VARCHAR},'yyyy-mm-dd') and psp.AMOUNT > 0 and psp.hoding_type = '03' and FP.FINPROD_TYPE2 not in ('F16', 'F24')
union all select '' PS, fp.mdate, psp.portfolio_id, psp.finprod_id, FP.FINPROD_TYPE2 CASHFLOWTYPE, '' CASH_TYPE, psp.amount CASHFLOW from ptl_sec_position psp left join FIN_PRODUCT fp on fp.FINPROD_ID = psp.FINPROD_ID where (FP.FINPROD_TYPE2 in ('F16', 'F24')) and psp.CDATE = to_date(#{searchDate,jdbcType=VARCHAR},'yyyy-mm-dd') - 1 and fp.mdate = to_date(#{searchDateFuture,jdbcType=VARCHAR},'yyyy-mm-dd') /*回购、拆借*/ union all select asset.ps, asset.mdate, assetadd.PORTFOLIO_ID, asset.trade_id, asset.FINPROD_TYPE2 CASHFLOWTYPE, '' CASH_TYPE, trade.m_trade_amt CASHFLOW from trd_product_deal asset left join fin_trade_product trade on asset.trade_id = trade.finprod_id left join trd_product_deal_add assetadd on asset.trade_id = assetadd.trade_id where asset.FINPROD_TYPE2 IN ('F03', 'F05', 'F02', 'F04','F08', 'F09', 'F25') and asset.ps = 'T01' and asset.is_cancel = 'N' and asset.TRADE_STATUS='01' and trade.BRANCH = '0' and asset.mDATE = to_date(#{searchDateFuture,jdbcType=VARCHAR},'yyyy-mm-dd')) tmp left join FIN_PRODUCT fp on tmp.portfolio_id = fp.FINPROD_MARKET_ID left join FIN_PRODUCT_ADD pa on PA.FINPROD_ID = fp.FINPROD_ID left join sys_user users on users.USER_NAME = pa.prod_manager where fp.P_FINPROD_ID is null
and users.USER_NAME in
#{item}
)
